"""Query complexity control.

Computes a deterministic request-complexity score from the same GraphQL
document and variables used by execution, strictly *before* any resolver,
indexed-entity read or subscription is established. Over-limit requests stop
with a single ``QUERY_COMPLEXITY_EXCEEDED`` GraphQL error without touching the
entity snapshots.

Scoring rules
-------------
* the root selection set of the selected operation is walked;
* every leaf field costs 1, a composite field costs only the sum of its
  children (the object container itself is free);
* repeated fields and distinct aliases are scored independently;
* fragments are inlined once at their spread position (inline fragments
  contribute their selection directly);
* introspection fields ``__schema`` and ``__type`` cost 0;
* list fields scale their sub-selection by an effective item upper bound read
  from a ``first`` or ``limit`` argument (literal positive integer first, then
  a variable bound of the same name), falling back to ``DEFAULT_LIST_BOUND``
  when absent, non-positive or non-integer.

The scorer walks the raw AST rather than the planner's merged selection so the
"repeated fields count separately" requirement holds regardless of the merge
that execution performs for response-key de-duplication.
"""

from __future__ import annotations

import os
from typing import Any, Dict, List, Optional

from .errors import PlanError
from .gql import FieldNode, FragmentSpread, InlineFragment, Var, parse_executable
from .schema import Schema, TypeInfo, named_of
from .planner import Planner

DEFAULT_LIST_BOUND = 1000
LIMIT_ENV_VAR = "GRAPHQL_QUERY_COMPLEXITY_LIMIT"

# field names whose value supplies a list item upper bound, in priority order
_BOUND_ARG_NAMES = ("first", "limit")


class QueryComplexityExceeded(PlanError):
    """The selected operation scores above the configured limit.

    Rendered as a normal GraphQL response on stdout (``data: null`` plus a
    single error whose ``extensions.code`` is QUERY_COMPLEXITY_EXCEEDED) rather
    than the usual {code, message} stderr error envelope.
    """

    def __init__(self, complexity: int, limit: int):
        super().__init__("QUERY_COMPLEXITY_EXCEEDED", f"query complexity {complexity} exceeds limit {limit}")
        self.complexity = complexity
        # Message carries the deterministic detail used by callers; code stays
        # available through ``self.code`` for the envelope renderer.
        self.limit = limit


def complexity_error_payload(complexity: Optional[int] = None,
                             limit: Optional[int] = None) -> Dict[str, Any]:
    """Build the GraphQL-style response emitted for an over-limit request."""
    error: Dict[str, Any] = {
        "message": "query complexity exceeds the configured limit",
        "indent": None,
    }
    if complexity is not None and limit is not None:
        error["message"] = (
            f"query complexity {complexity} exceeds the configured limit {limit}"
        )
    error.pop("indent")
    error["extensions"] = {"code": "QUERY_COMPLEXITY_EXCEEDED"}
    return {"data": None, "errors": [error]}


def load_complexity_limit(raw: Optional[str]) -> Optional[int]:
    """Validate the GRAPHQL_QUERY_COMPLEXITY_LIMIT value.

    Returns ``None`` when the control is disabled (variable absent or ``"0"``);
    otherwise the positive integer limit.
    """
    if raw is None:
        normalised = None
    else:
        normalised = raw.strip()
        if normalised == "":
            normalised = None
    if normalised is None:
        return None
    try:
        # ``int`` accepts e.g. "3", "-2", "+4", but rejects decimals ("1.5"),
        # whitespace-only values and non-numeric text. Python's acceptance of
        # underscores ("1_0") and surrounding whitespace is fine; we strip
        # surrounding whitespace ourselves so empty/blank is disabled.
        value = int(normalised)
    except (TypeError, ValueError):
        raise PlanError(
            "INVALID_QUERY_COMPLEXITY_LIMIT",
            f"value {raw!r} must be a non-negative integer",
        )
    if value < 0:
        raise PlanError(
            "INVALID_QUERY_COMPLEXITY_LIMIT",
            "value must be a non-negative integer",
        )
    if value == 0:
        return None
    return value


def load_limit_from_env(environ: Optional[Dict[str, Optional[str]]] = None) -> Optional[int]:
    """Read and validate the limit straight from the process environment."""
    env = os.environ if environ is None else environ
    return load_complexity_limit(env.get(LIMIT_ENV_VAR))


class ComplexityCalculator(Planner):
    """Scores the selected operation against the schema.

    Inherits the planner's operation selection, variable declarations,
    fragment bookkeeping and type-condition matching, but performs its own raw
    selection walk so repeated fields are never merged away.
    """

    def __init__(self, schema: Schema, variables: Dict[str, Any]):
        super().__init__(schema, variables)
        self.op_type: Optional[str] = None

    def score(
        self,
        query_text: str,
        source: str,
        operation_name: Optional[str],
        op_types: Optional[List[str]] = None,
    ) -> int:
        """Parse, select the operation and return its complexity.

        ``op_types`` optionally restricts which operations a concrete command
        supports (e.g. query-exec selects "query"). Selection and document
        problems surface through the same PlanError codes the command already
        uses.
        """
        operations, self.fragments = parse_executable(query_text, source)
        op = self._select_operation(operations, staticmethod(lambda: None) or operation_name)
        # The base selector is command specific; re-select via the hook below.
        raise NotImplementedError  # pragma: no cover

    def _select_operation(self, operations, operation_name):  # pragma: no cover
        return operations, operation_name

    def score_operation(self, op, var_map: bool = True) -> int:
        """Score an already-selected Operation; var_map populated by caller."""
        root_name = self.schema.roots.get(self.op_type)
        root_info = self.schema.types.get(root_name) if root_name else None
        if root_info is None:
            raise PlanError(
                "UnknownField",
                f"schema does not define a root type for {self.op_type} operations",
            )
        return self._walk_selections(op.selection_set, root_info, [])

    def _resolve_bound_value(self, value: Any) -> Optional[int]:
        """Resolve a first/limit argument to a positive integer, or None."""
        if isinstance(value, Var):
            name = value.name
