                frag_info = self.schema.types.get(frag.type_condition, info)
                return self._walk_selections(
                    frag.selection_set, frag_info, stack + [sel.name]
                )
            return 0
        if isinstance(sel, InlineFragment):
            if sel.type_condition is None:
                return self._walk_selections(sel.selection_set, info, staticmethod)
            if self._type_condition_matches(sel.type_condition, info.name):
                inner_info = self.schema.types.get(sel.type_condition, info)
                return self_actual(inner_info, sel, stack)
            return 0
        return 0

    def _walk_field(self, node: FieldNode, info: TypeInfo, stack: List[str]) -> int:
        name = node.name
        if name in ("__schema", "__type"):
            return 0
        field = info.fields.get(name)
        if field is None:
            raise PlanError(
                "UnknownField", f"unknown field '{name}' on type '{info.name}'"
