        from .subscription import _is_list_type
        if _is_list_type(field.type_ref):
            inner *= self._bound_for(node)
        return inner

    def score_document(
        self,
        query_text: str,
        source: str,
        score_operation_name: Optional[str],
        op_kind: str,
    ) -> int:
        """Parse document, select the operation of ``op_kind`` and score it."""
        operations, self.fragments = parse_executable(query_text, source)
        op = _select_named_or_unique(operations, score_operation_name, op_kind)
        self.op_type = op.op_type
        self.var_map = {}
        for name, type_ref, default, has_default in op.var_defs:
            if name in self.var_map:
