    if len(matching) == 1:
        return matching[0]
    if not operations:
        raise PlanError("InvalidRequest", "document contains no operations")
    if len(matching) == 0:
        raise PlanError(
            "UnsupportedOperation",
            f"{op_kind} operations are not supported",
        )
